const allPhrases = [...phrases, ...runtimePhrases, ...auditPhrases];
const byKey = Object.fromEntries(allPhrases.map(([key, en, fa, ps]) => [key, { en, fa, ps }])) as Record<string, Record<LegacyLocale, string>>;
const keyByEnglish = Object.fromEntries(allPhrases.map(([key, en]) => [en, key]));

export function translateLegacyText(value: string, locale: LegacyLocale): string {
  const key = keyByEnglish[value.trim()];
  if (key) return byKey[key][locale];
  const greeting = value.match(/^Good morning, (.+)\. Here is an overview of your school today\.$/);
  if (greeting) {
    const messages = { en: `Good morning, ${greeting[1]}. Here is an overview of your school today.`, fa: `صبح بخیر، ${greeting[1]}. این گزارش امروز مکتب شما است.`, ps: `سهار مو پخیر، ${greeting[1]}. دا د نن ورځې د ښوونځي لنډیز دی.` };
    return messages[locale];
  }
  const attendanceCount = value.match(/^(\d+) absent • (\d+) late$/);
  if (attendanceCount) {
    const messages = { en: `${attendanceCount[1]} absent • ${attendanceCount[2]} late`, fa: `${attendanceCount[1]} غایب • ${attendanceCount[2]} ناوقت`, ps: `${attendanceCount[1]} غیر حاضر • ${attendanceCount[2]} ناوخته` };
    return messages[locale];
  }
  const feeReminder = value.match(/^(.+) has AFN ([\d,]+) remaining$/);
  if (feeReminder) {
    const messages = { en: `${feeReminder[1]} has AFN ${feeReminder[2]} remaining`, fa: `${feeReminder[1]} مبلغ ${feeReminder[2]} افغانی باقی‌مانده دارد`, ps: `${feeReminder[1]} ${feeReminder[2]} افغانۍ پاتې لري` };
    return messages[locale];
  }
  const generatedReport = value.match(/^(.+) report is ready\.$/);
  if (generatedReport) {
    const messages = { en: `${generatedReport[1]} report is ready.`, fa: `گزارش ${generatedReport[1]} آماده است.`, ps: `د ${generatedReport[1]} راپور چمتو دی.` };
    return messages[locale];
  }
  const accountCreated = value.match(/^Teacher account created for (.+)\.$/);
  if (accountCreated) {
    const messages = { en: `Teacher account created for ${accountCreated[1]}.`, fa: `حساب استاد برای ${accountCreated[1]} ایجاد شد.`, ps: `د ${accountCreated[1]} لپاره د ښوونکي حساب جوړ شو.` };
    return messages[locale];
  }
  const credentialsPrepared = value.match(/^New temporary credentials prepared for (.+)\.$/);
  if (credentialsPrepared) {
    const messages = { en: `New temporary credentials prepared for ${credentialsPrepared[1]}.`, fa: `اعتبارنامه موقت جدید برای ${credentialsPrepared[1]} آماده شد.`, ps: `د ${credentialsPrepared[1]} لپاره نوي لنډمهاله معلومات چمتو شول.` };
    return messages[locale];
  }
  const marksRange = value.match(/^Marks for (.+) must be between 0 and ([\d.]+)\.$/);
  if (marksRange) {
    const messages = { en: `Marks for ${marksRange[1]} must be between 0 and ${marksRange[2]}.`, fa: `نمرات ${marksRange[1]} باید بین ۰ و ${marksRange[2]} باشد.`, ps: `د ${marksRange[1]} نمرې باید د ۰ او ${marksRange[2]} ترمنځ وي.` };
    return messages[locale];
  }
  const resultCount = value.match(/^(\d+) result(s?) saved successfully\.$/);
  if (resultCount) {
    const messages = { en: value, fa: `${resultCount[1]} نتیجه با موفقیت ذخیره شد.`, ps: `${resultCount[1]} پایله په بریالیتوب وساتل شوه.` };
    return messages[locale];
  }
  return value;
}
